pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {LiquidityPool} from "../src/LiquidityPool.sol";

contract InvMutTest is Test {
    LiquidityPool c;
    function setUp() public { c = new LiquidityPool(0, bytes16(0), address(this), address(this), address(this)); }
    function testRegression_property() public {
        bool ok;
        vm.prank(address(this));
        try c.rely(address(this)) { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}
